import re

def _parse_goal(goal):
    # e.g. "put a clean apple in fridge." / "put a kettle in shelf."
    m = re.search(r"put (?:a |an |the )?(.+?) (?:in|on|to) (?:a |an |the )?(.+?)(?:[.,]|$)", goal.strip(), re.I)
    if not m:
        return None, None
    obj = m.group(1).strip().lower()
    rec = m.group(2).strip().lower()
    # drop qualifiers like "clean"
    obj = re.sub(r"^(clean|dirty|hot|cold|warm)\s+", "", obj)
    return obj, rec

def _norm(s):
    return re.sub(r"\s+", " ", s.strip().lower())

def _find_in_text(text, candidates, start=0):
    # return (name, index) for first candidate found in text
    best = None
    for c in candidates:
        for m in re.finditer(r"\b" + re.escape(c) + r"\b", text):
            if m.start() >= start and (best is None or m.start() < best[1]):
                best = (c, m.start())
    return best

def _receptacle_names(obs):
    # names like "cabinet 9", "shelf 1", "fridge 1"
    names = []
    for m in re.finditer(r"\b([a-z]+(?: ?\d+)?)\b(?=[ ,.\n])", obs):
        pass
    # simpler: split on commas
    for part in re.split(r"[,\n]", obs):
        part = part.strip()
        if not part:
            continue
        m = re.match(r"^(?:a |an |the )?([a-z]+(?: \d+)?)$", part, re.I)
        if m:
            names.append(m.group(1).lower())
    return names

def _objects_on(obs):
    # text after "you see" / "On the X, you see"
    m = re.search(r"you see (.*)", obs, re.I | re.S)
    if not m:
        return []
    txt = m.group(1)
    txt = re.sub(r"\band\b", ",", txt)
    objs = []
    for part in re.split(r"[,\n]", txt):
        part = part.strip().rstrip(".")
        mm = re.match(r"^(?:a |an |the )?([a-z]+(?: \d+)?)$", part, re.I)
        if mm:
            objs.append(mm.group(1).lower())
    return objs

def _current_receptacle(obs):
    m = re.search(r"You arrive at ([a-z]+(?: \d+)?)", obs, re.I)
    if m:
        return m.group(1).lower()
    m = re.search(r"\bat ([a-z]+(?: \d+)?)", obs, re.I)
    if m:
        return m.group(1).lower()
    return None

def _object_matches(goal_obj, seen):
    # goal_obj may be "kettle", seen "kettle 2"; or goal_obj could be "apple 1"
    g = goal_obj.lower()
    if re.search(r"\b" + re.escape(g) + r"\b", seen):
        return True
    # strip trailing number from goal and match base
    base = re.sub(r"\s+\d+$", "", g)
    if base != g and re.search(r"\b" + re.escape(base) + r"\b", seen):
        return True
    return False

def solve(env, goal):
    obj, rec = _parse_goal(goal)
    if obj is None:
        return

    obs = env.observation
    steps = 0
    MAX = 48

    # Phase 1: locate object
    target_obj = None
    target_rec = None
    visited = set()

    while steps < MAX:
        # check current observation for object
        if _object_matches(obj, obs):
            # if we see the object here, take it
            objs = _objects_on(obs)
            cand = None
            for o in objs:
                if _object_matches(obj, o):
                    cand = o
                    break
            if cand:
                cur = _current_receptacle(obs)
                if cur is None:
                    cur = "here"
                feedback = env.step("take %s from %s" % (cand, cur))
                steps += 1
                obs = feedback
                if "pick up" in obs.lower() or "you pick" in obs.lower():
                    target_obj = cand
                    break
                # if take failed, continue
            else:
                # goal object mentioned but not listed; maybe already holding it
                target_obj = obj
                break

        # determine where to go
        recs = _receptacle_names(env.observation)
        # find unvisited receptacles
        unvisited = [r for r in recs if r not in visited]
        if not unvisited:
            # try going to goal receptacle directly in case object is there
            if rec not in visited:
                unvisited = [rec]
            else:
                break
        nxt = unvisited[0]
        visited.add(nxt)
        feedback = env.step("go to %s" % nxt)
        steps += 1
        obs = feedback

    if target_obj is None:
        # maybe already held; try to move goal name
        target_obj = obj

    # Phase 2: go to goal receptacle and move object
    cur_rec = _current_receptacle(obs)
    if cur_rec != rec:
        # try going to rec
        feedback = env.step("go to %s" % rec)
        steps += 1
        obs = feedback
        if steps < MAX and rec not in obs.lower():
            # rec maybe not exact; try variations
            for r in _receptacle_names(obs):
                if r.startswith(rec):
                    feedback = env.step("go to %s" % r)
                    steps += 1
                    obs = feedback
                    break

    # move
    cmd = "move %s to %s" % (target_obj, rec)
    feedback = env.step(cmd)
    steps += 1
    obs = feedback

    if "move" not in obs.lower() and steps < MAX:
        # try with exact object name from obs
        objs = _objects_on(obs) if False else []
        # fallback: if we know the numbered object
        if target_obj and target_obj != obj:
            env.step("move %s to %s" % (target_obj, rec))
