import re

def _norm(s):
    return re.sub(r"\s+", " ", s.strip().lower())

def _parse_goal(goal):
    m = re.search(r"put\s+(?:a|an|the)?\s*(.+?)\s+(?:in|on|to)\s+(?:a|an|the)?\s*(.+?)\s*[.,]?$", goal.strip(), re.I)
    if not m:
        return None, None
    obj = m.group(1).strip().lower()
    rec = m.group(2).strip().lower()
    obj = re.sub(r"^(clean|dirty|hot|cold|warm)\s+", "", obj)
    rec = re.sub(r"^(clean|dirty|hot|cold|warm)\s+", "", rec)
    return obj, rec

def _base(name):
    return re.sub(r"\s+\d+$", "", name.strip().lower())

def _receptacle_names(text):
    names = []
    for part in re.split(r"[,\n]", text):
        part = part.strip().rstrip(".")
        if not part:
            continue
        m = re.match(r"^(?:a|an|the)?\s*([a-z]+(?:\s+\d+)?)$", part, re.I)
        if m:
            names.append(m.group(1).lower())
    return names

def _objects_on(obs):
    m = re.search(r"you see (.*)", obs, re.I | re.S)
    if not m:
        return []
    txt = m.group(1)
    txt = re.sub(r"\band\b", ",", txt)
    objs = []
    for part in re.split(r"[,\n]", txt):
        part = part.strip().rstrip(".")
        mm = re.match(r"^(?:a|an|the)?\s*([a-z]+(?:\s+\d+)?)$", part, re.I)
        if mm:
            objs.append(mm.group(1).lower())
    return objs

def _current_receptacle(obs):
    m = re.search(r"You arrive at ([a-z]+(?:\s+\d+)?)", obs, re.I)
    if m:
        return m.group(1).lower()
    m = re.search(r"\bat ([a-z]+(?:\s+\d+)?)", obs, re.I)
    if m:
        return m.group(1).lower()
    return None

def _matches(goal_obj, name):
    g = goal_obj.lower()
    n = name.lower()
    if re.search(r"\b" + re.escape(g) + r"\b", n):
        return True
    gb = _base(g)
    nb = _base(n)
    if gb and gb == nb:
        return True
    return False

def _open_if_needed(env, rec, obs):
    # If receptacle looks closed, try opening it.
    if re.search(r"\b%s\b.*\bclosed\b" % re.escape(rec), obs, re.I) or re.search(r"\bclosed\b.*\b%s\b" % re.escape(rec), obs, re.I):
        fb = env.step("open %s" % rec)
        return fb
    return obs

def solve(env, goal):
    obj, rec = _parse_goal(goal)
    if obj is None or rec is None:
        return

    obs = env.observation
    steps = 0
    MAX = 48

    # Try to find the goal receptacle name variant present in room listing.
    rec_names = _receptacle_names(obs)
    goal_rec = None
    for r in rec_names:
        if r == rec or _base(r) == _base(rec):
            goal_rec = r
            break
    if goal_rec is None:
        goal_rec = rec

    # Phase 1: locate and take the object.
    target_obj = None
    visited = set()
    # Also remember the room receptacle list from the first observation.
    room_recs = [r for r in rec_names if _base(r) != _base(goal_rec)]

    while steps < MAX:
        # If object is visible here, take it.
        objs = _objects_on(obs)
        found = None
        for o in objs:
            if _matches(obj, o):
                found = o
                break
        if found:
            cur = _current_receptacle(obs)
            if cur is None:
                cur = "here"
            fb = env.step("take %s from %s" % (found, cur))
            steps += 1
            obs = fb
            if "pick up" in obs.lower() or "you pick" in obs.lower():
                target_obj = found
                break
            # if take failed, continue searching
            continue

        # Check if already holding the object (inventory feedback).
        if re.search(r"you (?:are|have) .*holding", obs, re.I) and _matches(obj, obs):
            target_obj = obj
            break

        # Otherwise move to an unvisited receptacle.
        candidates = [r for r in room_recs if r not in visited]
        # Prefer goal receptacle last if object not found yet? No—search all.
        if not candidates:
            break
        nxt = candidates[0]
        visited.add(nxt)
        fb = env.step("go to %s" % nxt)
        steps += 1
        obs = fb
        # If it's closed, open it so contents are visible.
        obs = _open_if_needed(env, nxt, obs)
        if "open" in env.observation.lower() and nxt in env.observation.lower():
            steps += 1
        # After opening, re-read observation for objects.
        if _current_receptacle(obs) == nxt:
            objs = _objects_on(obs)
            for o in objs:
                if _matches(obj, o):
                    fb = env.step("take %s from %s" % (o, nxt))
                    steps += 1
                    obs = fb
                    if "pick up" in obs.lower() or "you pick" in obs.lower():
                        target_obj = o
                    break
            if target_obj:
                break

    if target_obj is None:
        # Last resort: assume we can move by goal name.
        target_obj = obj

    # Phase 2: go to goal receptacle (open if closed) and move object there.
    cur = _current_receptacle(obs)
    if cur != goal_rec:
        fb = env.step("go to %s" % goal_rec)
        steps += 1
        obs = fb
        # If nothing happens, try a variant that matches a listed receptacle.
        if "nothing happens" in obs.lower() or steps >= MAX:
            # Try each room receptacle whose base matches goal base.
            for r in _receptacle_names(env.observation):
                if _base(r) == _base(goal_rec) and r != goal_rec:
                    fb = env.step("go to %s" % r)
                    steps += 1
                    obs = fb
                    goal_rec = r
                    break

    obs = _open_if_needed(env, goal_rec, obs)
    if "open" in obs.lower() and goal_rec in obs.lower():
        steps += 1

    # Move the object.
    fb = env.step("move %s to %s" % (target_obj, goal_rec))
    steps += 1
    obs = fb

    # If move failed, try opening again then moving.
    if ("nothing happens" in obs.lower() or "closed" in obs.lower()) and steps < MAX:
        env.step("open %s" % goal_rec)
        steps += 1
        env.step("move %s to %s" % (target_obj, goal_rec))
